export const THEMES = RAW.trim().split('\n').map(line => {
  const [title, words] = line.split(':');
  return {
    title: title.trim(),
    words: [...new Set(words.trim().split(/\s+/).map(w => w.replace(/ß/g, 'SS')))],
  };
});
